  1	import { create } from "zustand";
  2	import { bridge } from "@/services";
  3	import type { ExtensionConfig, GenerationConfig } from "shared/types";
  4	import type { MCPServerConfig, ModelConfig, ThinkingMode, SlashCommandInfo } from "@consilium/agent-sdk";
  5	
  6	export const DEFAULT_EXTENSION_CONFIG: ExtensionConfig = {
  7	  executablePath: "",
  8	  yoloMode: false,
  9	  autosave: true,
 10	  useCtrlEnterToSend: false,
 11	  enableNewConversationShortcut: false,
 12	  environmentVariables: {},
 13	  showThinkingContent: true,
 14	  showThinkingExpanded: true,
 15	  version: "",
 16	  generationConfig: {
 17	    temperature: 0.7,
 18	    topP: 0.9,
 19	    maxTokens: 32000,
 20	  },
 21	  apiKey: "",
 22	  apiProviderType: "",
 23	  apiBaseUrl: "",
 24	  apiCustomHeaders: {},
 25	  defaultThinkModel: "",
 26	  defaultDoModel: "",
 27	};
 28	
 29	export function getModelThinkingMode(model: ModelConfig): ThinkingMode {
 30	  if (model.name.toLowerCase().includes("think")) {
 31	    return "always";
 32	  }
 33	  if (model.capabilities.includes("always_thinking")) {
 34	    return "always";
 35	  }
 36	  if (model.capabilities.includes("thinking")) {
 37	    return "switch";
 38	  }
 39	  return "none";
 40	}
 41	
 42	export function isImageModel(model: ModelConfig): boolean {
 43	  return model.capabilities.includes("image_in");
 44	}
 45	
 46	export function isVideoModel(model: ModelConfig): boolean {
 47	  return model.capabilities.includes("video_in");
 48	}
 49	
 50	export function getModelById(models: ModelConfig[], id: string): ModelConfig | undefined {
 51	  return models.find((m) => m.id === id);
 52	}
 53	
 54	export interface MediaRequirements {
 55	  image: boolean;
 56	  video: boolean;
 57	}
 58	
 59	export function getModelsForMedia(models: ModelConfig[], mediaReq: MediaRequirements): ModelConfig[] {
 60	  return models.filter((m) => {
 61	    if (mediaReq.image && !isImageModel(m)) {
 62	      return false;
 63	    }
 64	    if (mediaReq.video && !isVideoModel(m)) {
 65	      return false;
 66	    }
 67	    return true;
 68	  });
 69	}
