 71	interface SettingsState {
 72	  currentModel: string;
 73	  thinkingEnabled: boolean;
 74	  extensionConfig: ExtensionConfig;
 75	  mcpServers: MCPServerConfig[];
 76	  mcpModalOpen: boolean;
 77	  workDirModalOpen: boolean;
 78	  currentWorkDir: string | null;
 79	  workspaceRoot: string | null;
 80	  models: ModelConfig[];
 81	  defaultModel: string | null;
 82	  defaultThinking: boolean;
 83	  modelsLoaded: boolean;
 84	  wireSlashCommands: SlashCommandInfo[];
 85	  slashCommands: SlashCommandInfo[];
 86	  isLoggedIn: boolean;
 87	  generationConfigOpen: boolean;
 88	  projectSetupSkipped: boolean;
 89	  autoLoadHistory: boolean;
 90	
 91	  setCurrentModel: (model: string) => void;
 92	  setThinkingEnabled: (enabled: boolean) => void;
 93	  updateModel: (modelId: string) => void;
 94	  toggleThinking: () => void;
 95	  setExtensionConfig: (config: ExtensionConfig) => void;
 96	  setGenerationConfigOpen: (open: boolean) => void;
 97	  updateGenerationConfig: (config: Partial<GenerationConfig>) => void;
 98	  setMCPServers: (servers: MCPServerConfig[]) => void;
 99	  setMCPModalOpen: (open: boolean) => void;
100	  setWorkDirModalOpen: (open: boolean) => void;
101	  setCurrentWorkDir: (workDir: string | null) => void;
102	  setWorkspaceRoot: (root: string | null) => void;
103	  initModels: (models: ModelConfig[], defaultModel: string | null, defaultThinking: boolean) => void;
104	  setWireSlashCommands: (commands: SlashCommandInfo[]) => void;
105	  setIsLoggedIn: (loggedIn: boolean) => void;
106	  getCurrentThinkingMode: () => ThinkingMode;
107	}
108	
109	export const useSettingsStore = create<SettingsState>((set, get) => ({
110	  currentModel: "",
111	  thinkingEnabled: false,
112	  extensionConfig: DEFAULT_EXTENSION_CONFIG,
113	  mcpServers: [],
114	  mcpModalOpen: false,
115	  workDirModalOpen: false,
116	  currentWorkDir: null,
117	  workspaceRoot: null,
118	  models: [],
119	  defaultModel: null,
120	  defaultThinking: false,
121	  modelsLoaded: false,
122	  wireSlashCommands: [],
123	  slashCommands: [],
124	  isLoggedIn: false,
125	  generationConfigOpen: false,
126	  projectSetupSkipped: false,
127	  autoLoadHistory: true,
128	
129	  setCurrentModel: (currentModel) => set({ currentModel }),
130	
131	  setThinkingEnabled: (thinkingEnabled) => set({ thinkingEnabled }),
132	
133	  updateModel: (modelId) => {
134	    const { models, defaultThinking } = get();
135	    const model = getModelById(models, modelId);
136	    if (!model) {
137	      return;
138	    }
139	
140	    const thinkingMode = getModelThinkingMode(model);
141	    let thinkingEnabled: boolean;
142	
143	    if (thinkingMode === "always") {
144	      thinkingEnabled = true;
145	    } else if (thinkingMode === "none") {
146	      thinkingEnabled = false;
147	    } else {
148	      // switch mode - use default preference
149	      thinkingEnabled = defaultThinking;
150	    }
151	
152	    set({ currentModel: modelId, thinkingEnabled });
153	    bridge.saveConfig({ model: modelId, thinking: thinkingEnabled });
154	  },
155	
156	  toggleThinking: () => {
157	    const { models, currentModel, thinkingEnabled } = get();
158	    const model = getModelById(models, currentModel);
159	    if (!model) {
160	      return;
161	    }
162	
163	    const thinkingMode = getModelThinkingMode(model);
164	    if (thinkingMode !== "switch") {
165	      return;
166	    } // Can only toggle in switch mode
167	
168	    const newThinking = !thinkingEnabled;
169	    set({ thinkingEnabled: newThinking, defaultThinking: newThinking });
170	    bridge.saveConfig({ model: currentModel, thinking: newThinking });
171	  },
172	
173	  setExtensionConfig: (extensionConfig) => set({ extensionConfig }),
174	
175	  setGenerationConfigOpen: (generationConfigOpen) => set({ generationConfigOpen }),
176	
177	  updateGenerationConfig: (partial) => {
178	    const { extensionConfig } = get();
179	    const newConfig = { ...extensionConfig.generationConfig, ...partial };
180	    set({
181	      extensionConfig: { ...extensionConfig, generationConfig: newConfig },
182	    });
183	    bridge.saveConfig({
184	      model: get().currentModel,
185	      thinking: get().thinkingEnabled,
186	      generation: newConfig,
187	    });
188	  },
189	
190	  setMCPServers: (mcpServers) => set({ mcpServers }),
191	
192	  setMCPModalOpen: (mcpModalOpen) => set({ mcpModalOpen }),
193	
194	  setWorkDirModalOpen: (workDirModalOpen) => set({ workDirModalOpen }),
195	
196	  setCurrentWorkDir: (currentWorkDir) => set({ currentWorkDir }),
197	
198	  setWorkspaceRoot: (workspaceRoot) => set({ workspaceRoot }),
199	
200	  initModels: (models, defaultModel, defaultThinking) => {
201	    const initialModel = defaultModel || (models.length > 0 ? models[0].id : "");
202	    const model = getModelById(models, initialModel);
203	
204	    let thinkingEnabled = false;
205	    if (model) {
206	      const thinkingMode = getModelThinkingMode(model);
207	      if (thinkingMode === "always") {
208	        thinkingEnabled = true;
209	      } else if (thinkingMode === "switch") {
210	        thinkingEnabled = defaultThinking;
211	      }
212	    }
213	
214	    set({
215	      models,
216	      defaultModel,
217	      defaultThinking,
218	      modelsLoaded: true,
219	      currentModel: initialModel,
220	      thinkingEnabled,
221	    });
222	  },
223	
224	  setWireSlashCommands: (commands) => {
225	    set({
226	      wireSlashCommands: commands,
227	      slashCommands: commands,
228	    });
229	  },
230	
231	  setIsLoggedIn: (isLoggedIn) => set({ isLoggedIn }),
232	
233	  getCurrentThinkingMode: () => {
234	    const { models, currentModel } = get();
235	    const model = getModelById(models, currentModel);
236	    if (!model) {
237	      return "none";
238	    }
239	    return getModelThinkingMode(model);
240	  },
241	}));
